const items = ($json.data && $json.data.node && $json.data.node.items && $json.data.node.items.nodes) || [];
const now = new Date();
now.setUTCHours(0, 0, 0, 0);
const DAY = 86400000;
const rows = items.map((item) => {
  const fields = {};
  for (const value of (item.fieldValues?.nodes || [])) {
    if (value.field && value.field.name) {
      fields[value.field.name] = value.date || value.name;
    }
  }
  const issue = item.content || {};
  const ageHours = issue.updatedAt ? Math.round((Date.now() - new Date(issue.updatedAt).getTime()) / 3600000) : 0;
  const status = fields.Workflow || 'No status';
  const target = fields['Target date'] || '';
  const targetTime = target ? new Date(target + 'T00:00:00Z').getTime() : null;
  const overdue = Boolean(targetTime && status !== 'Done' && targetTime < now.getTime());
  const dueSoon = Boolean(targetTime && status !== 'Done' && !overdue && targetTime - now.getTime() <= 7 * DAY);
  return {
    number: issue.number,
    title: issue.title,
    status,
    agent: fields.Agent || 'Unassigned',
    priority: fields.Priority || '-',
    review: fields.Review || '-',
    target,
    overdue,
    dueSoon,
    ageHours,
  };
});
const by = (key) => rows.reduce((acc, row) => { acc[row[key]] = (acc[row[key]] || 0) + 1; return acc; }, {});
const active = rows.filter((row) => row.status !== 'Done');
const stale = active.filter((row) => row.ageHours > 48);
const overdue = active.filter((row) => row.overdue);
const dueSoon = active.filter((row) => row.dueSoon);
const missingTarget = active.filter((row) => !row.target);
const table = active
  .sort((a, b) => String(a.priority).localeCompare(String(b.priority)))
  .map((row) => '| #' + row.number + ' | ' + row.title + ' | ' + row.status + ' | ' + row.agent + ' | ' + row.priority + ' | ' + row.review + ' | ' + (row.target || 'none') + (row.overdue ? ' **overdue**' : row.dueSoon ? ' *due soon*' : '') + ' | ' + row.ageHours + 'h |')
  .join('\n');
const listing = (list) => list.length ? list.map((row) => '#' + row.number + ' ' + row.title + ' (' + (row.target || 'no date') + ')').join('; ') : 'none';
const body = '# Ancya delivery report\n\n## Open work\n\n| Issue | Title | Status | Agent | Priority | Review | Target | Last update |\n|---|---|---|---|---|---|---|---|\n' + table + '\n\n## Schedule\n\n- Overdue: ' + listing(overdue) + '\n- Due within 7 days: ' + listing(dueSoon) + '\n- No target date: ' + (missingTarget.length ? missingTarget.map((row) => '#' + row.number).join(', ') : 'none') + '\n\n## Metrics\n\n- Open items: ' + active.length + '\n- By status: ' + JSON.stringify(by('status')) + '\n- By agent: ' + JSON.stringify(by('agent')) + '\n- Stale over 48h: ' + (stale.length ? stale.map((row) => '#' + row.number).join(', ') : 'none') + '\n';
return [{ json: { metrics: { overdue: overdue.length, dueSoon: dueSoon.length, missingTarget: missingTarget.length }, body, prompt: 'Write a concise project-manager narrative for this week. Use only the data below. Call out overdue items, items due within 7 days, blockers and decisions needed from Antony, then give the next three actions.\n\n' + body } }];

const narrative = ($json.message && $json.message.content) ? $json.message.content.trim() : '';
const source = $('Build metrics').item.json;
const body = source.body + '
## Summary

' + (narrative || 'No narrative generated.') + '
';
return [{ json: { body } }];
